        ESP_EARLY_LOGE(TAG, "Failed to register PSRAM ISR!");
        return ret;
    }

    ret = esp_psram_mspi_mb_init();
    if (ret != ESP_OK) {
        ESP_EARLY_LOGE(TAG, "Failed to initialize PSRAM MSPI memory barrier!");
        return ret;
    }

    return ret;
}

