MSPI_INIT_ATTR void sys_rtc_init(const soc_reset_reason_t *rst_reas)
{
#if CONFIG_IDF_TARGET_ESP32P4
#define RWDT_RESET           RESET_REASON_CORE_RWDT
#define MWDT_RESET           RESET_REASON_CORE_MWDT
#else
#define RWDT_RESET           RESET_REASON_CORE_RTC_WDT
#define MWDT_RESET           RESET_REASON_CORE_MWDT0
#endif

#ifndef CONFIG_BOOTLOADER_WDT_ENABLE
    // from panic handler we can be reset by RWDT or TG0WDT
    if (rst_reas[0] == RWDT_RESET || rst_reas[0] == MWDT_RESET
#if !CONFIG_ESP_SYSTEM_SINGLE_CORE_MODE
            || rst_reas[1] == RWDT_RESET || rst_reas[1] == MWDT_RESET
#endif
       ) {
        wdt_hal_context_t rtc_wdt_ctx = RWDT_HAL_CONTEXT_DEFAULT();
        wdt_hal_write_protect_disable(&rtc_wdt_ctx);
        wdt_hal_disable(&rtc_wdt_ctx);
        wdt_hal_write_protect_enable(&rtc_wdt_ctx);
    }
#endif

    // Configure the power related stuff. After this the MSPI timing tuning can be done.
    esp_rtc_init();
}

#if !CONFIG_APP_BUILD_TYPE_PURE_RAM_APP
static NOINLINE_ATTR IRAM_ATTR void flash_init_state(void)
{
    /**
     * This function initialise the Flash chip to the user-defined settings.
     *
     * In bootloader, we only init Flash (and MSPI) to a preliminary state, for being flexible to
     * different chips.
     * In this stage, we re-configure the Flash (and MSPI) to required configuration
     */
    spi_flash_init_chip_state();
    // This function needs to be called when PLL is enabled. Needs to be called after spi_flash_init_chip_state in case
    // some state of flash is modified.
    mspi_timing_flash_tuning();
}

MSPI_INIT_ATTR void mspi_init(void)
{
#if CONFIG_ESPTOOLPY_OCT_FLASH && !CONFIG_ESPTOOLPY_FLASH_MODE_AUTO_DETECT
    bool efuse_opflash_en = efuse_ll_get_flash_type();
    if (!efuse_opflash_en) {
        ESP_DRAM_LOGE(TAG, "Octal Flash option selected, but EFUSE not configured!");
        abort();
    }
#endif

    esp_mspi_pin_init();
    // For Octal flash, it's hard to implement a read_id function in OPI mode for all vendors.
    // So we have to read it here in SPI mode, before entering the OPI mode.
    bootloader_flash_update_id();

    flash_init_state();

    esp_mmu_map_init(); //required by image_process() and flash_mmap APIs

#if !CONFIG_APP_BUILD_TYPE_ELF_RAM
#if CONFIG_SPIRAM_FLASH_LOAD_TO_PSRAM
    ESP_ERROR_CHECK(image_process());
#endif
#endif

#if CONFIG_SPIRAM_BOOT_HW_INIT
    if (esp_psram_chip_init() != ESP_OK) {
#if CONFIG_SPIRAM_IGNORE_NOTFOUND
        ESP_DRAM_LOGE(TAG, "Failed to init external RAM; continuing without it.");
#else
        ESP_DRAM_LOGE(TAG, "Failed to init external RAM!");
        abort();
#endif
    }
#endif

#if CONFIG_SPIRAM_BOOT_INIT
    if (esp_psram_init() != ESP_OK) {
#if CONFIG_SPIRAM_ALLOW_BSS_SEG_EXTERNAL_MEMORY
        ESP_DRAM_LOGE(TAG, "Failed to init external RAM, needed for external .bss segment");
        abort();
#endif
    }
#endif
}
#endif // !CONFIG_APP_BUILD_TYPE_PURE_RAM_APP

#if CONFIG_IDF_TARGET_ESP32 && !CONFIG_APP_BUILD_TYPE_RAM && !CONFIG_SPIRAM_BOOT_HW_INIT
/*
 * Adjust flash configuration. This must be placed in IRAM because running from flash,
 * while it is being reconfigured, will result in corrupt data being read.
 */
NOINLINE_ATTR IRAM_ATTR static void configure_flash(esp_image_header_t *fhdr)
{
    bootloader_flash_gpio_config(fhdr);
    bootloader_flash_dummy_config(fhdr);
    bootloader_flash_clock_config(fhdr);
    bootloader_flash_cs_timing_config();
}
#endif // CONFIG_IDF_TARGET_ESP32 && !CONFIG_APP_BUILD_TYPE_RAM && !CONFIG_SPIRAM_BOOT_HW_INIT

/*
 * Initialize other parts of the system, including other CPUs.
 * As CPU0 needs to disable the cache in system_early_init function, the other cores are not allowed to run with the
 * cache until the SYS_STARTUP_FN.
 */
NOINLINE_ATTR static void system_early_init(const soc_reset_reason_t *rst_reas)
  cache_set_idrom_mmu_size(cache_mmu_irom_size,
                           CACHE_DROM_MMU_MAX_END - cache_mmu_irom_size);
#endif /* CONFIG_ESP_ROM_NEEDS_SET_CACHE_MMU_SIZE */

#if CONFIG_ESP_SYSTEM_BBPLL_RECALIB
  recalib_bbpll();
#endif

#ifdef CONFIG_ESPRESSIF_REGION_PROTECTION
  /* Configure region protection */

  esp_cpu_configure_region_protection();
#endif

  /* Configure the power related stuff. */

  esp_rtc_init();

  ets_printf("P4BOOT:04 rtc_ready\n");

  esp_mspi_pin_init();

  ets_printf("P4BOOT:05 mspi_pins_ready\n");

  /* Configure SPI Flash chip state */

  spi_flash_init_chip_state();

  esp_mmu_map_init();

  ets_printf("P4BOOT:06 flash_mmu_ready\n");

  /* bootloader_init() has already brought up the MSPI and CPLL.  Complete
   * the application clock setup before enabling external RAM: changing the
   * RTC/CPU clock tree after PSRAM has been mapped destabilizes the shared
   * MSPI clock domain on this board.
   */

  esp_clk_init();

  ets_printf("P4BOOT:07 clocks_ready\n");

  /* The second-stage bootloader leaves the RTC watchdog enabled to guard
   * application startup.  PSRAM training and mapping can exceed that early
   * boot window, so hand the watchdog off before starting external RAM.
   */

  wdt_hal_context_t rwdt_ctx = RWDT_HAL_CONTEXT_DEFAULT();
  wdt_hal_write_protect_disable(&rwdt_ctx);
  wdt_hal_set_flashboot_en(&rwdt_ctx, false);
  wdt_hal_disable(&rwdt_ctx);
  wdt_hal_write_protect_enable(&rwdt_ctx);

  /* The ROM/second-stage path also enables the LP analog Super WDT.  Its
   * reset is reported as a full-chip/power-on reset rather than RWDT, so it
   * must be handed off separately before the relatively long PSRAM setup.
   */

  REG_WRITE(LP_WDT_SWD_WPROTECT_REG, LP_WDT_SWD_WKEY_VALUE);
  REG_SET_BIT(LP_WDT_SWD_CONFIG_REG, LP_WDT_SWD_DISABLE);
  REG_WRITE(LP_WDT_SWD_WPROTECT_REG, 0);

  ets_printf("P4BOOT:08 wdts_disabled\n");

#ifdef CONFIG_ESPRESSIF_SPIRAM
  ets_printf("P4BOOT:09 psram_chip_init\n");
  ret = esp_psram_chip_init();
  ets_printf("P4BOOT:10 psram_chip_ret=%d\n", ret);
  if (ret != ESP_OK)
    {
#  ifndef CONFIG_ESPRESSIF_SPIRAM_IGNORE_NOTFOUND
      PANIC();
#  endif
    }

#  ifdef CONFIG_ESPRESSIF_SPIRAM_BOOT_INIT
  if (ret == ESP_OK)
    {
      ets_printf("P4BOOT:11 psram_map_init\n");
      ret = esp_psram_init();
      ets_printf("P4BOOT:12 psram_map_ret=%d\n", ret);
      if (ret != ESP_OK)
        {
#    ifndef CONFIG_ESPRESSIF_SPIRAM_IGNORE_NOTFOUND
          PANIC();
#    endif
        }
    }
#  endif
#endif

  esp_mspi_pin_reserve();

  bootloader_init_mem();

  ets_printf("P4BOOT:13 memory_ready\n");

#ifdef CONFIG_ESPRESSIF_SPIRAM_MEMTEST
  if (esp_psram_is_initialized() && !esp_psram_extram_test())
    {
      PANIC();
    }
#endif

#ifdef CONFIG_ESPRESSIF_SPIRAM_ALLOW_BSS_SEG_EXTERNAL_MEMORY
  esp_psram_bss_init();

    /*------------------------------------------------------------------------------
    * After mapping, we DON'T care about the PSRAM PHYSICAL ADDRESS ANYMORE!
    *----------------------------------------------------------------------------*/

    //------------------------------------Configure other sections in PSRAM-------------------------------------//
    uintptr_t ext_section_start = UINTPTR_MAX;
    uintptr_t ext_section_end = 0;

#if CONFIG_SPIRAM_ALLOW_BSS_SEG_EXTERNAL_MEMORY
    ext_section_start = (uintptr_t)&_ext_ram_bss_start;
    ext_section_end = (uintptr_t)&_ext_ram_bss_end;
#endif  //#if CONFIG_SPIRAM_ALLOW_BSS_SEG_EXTERNAL_MEMORY

#if CONFIG_SPIRAM_ALLOW_NOINIT_SEG_EXTERNAL_MEMORY
    if ((uintptr_t)&_ext_ram_noinit_start < ext_section_start) {
        ext_section_start = (uintptr_t)&_ext_ram_noinit_start;
    }
    if ((uintptr_t)&_ext_ram_noinit_end > ext_section_end) {
        ext_section_end = (uintptr_t)&_ext_ram_noinit_end;
    }
#endif  //#if CONFIG_SPIRAM_ALLOW_NOINIT_SEG_EXTERNAL_MEMORY

    if ((ext_section_start != UINTPTR_MAX) || (ext_section_end != 0)) {
        assert(ext_section_end >= ext_section_start);
        uint32_t ext_section_size = ext_section_end - ext_section_start;
        ESP_EARLY_LOGV(TAG, "ext_section_size is %" PRIu32, ext_section_size);
        s_psram_ctx.regions_to_heap[PSRAM_MEM_8BIT_ALIGNED].vaddr_start += ext_section_size;
        s_psram_ctx.regions_to_heap[PSRAM_MEM_8BIT_ALIGNED].size -= ext_section_size;
    }

#if CONFIG_IDF_TARGET_ESP32
    s_psram_ctx.regions_to_heap[PSRAM_MEM_8BIT_ALIGNED].size -= esp_himem_reserved_area_size() - 1;
    s_psram_ctx.regions_to_heap[PSRAM_MEM_8BIT_ALIGNED].vaddr_end -= esp_himem_reserved_area_size();
#endif
}

esp_err_t esp_psram_chip_init(void)
{
    return s_psram_chip_init();
}

esp_err_t esp_psram_init(void)
{
    esp_err_t ret = ESP_FAIL;

    if (!s_psram_ctx.is_chip_initialised) {
        ret = esp_psram_chip_init();
        if (ret != ESP_OK) {
            return ret;
        }
    }

#if CONFIG_IDF_TARGET_ESP32P4 && !CONFIG_ESP32P4_SELECTS_REV_LESS_V3
    // This workaround is only needed for P4 rev 300 (3.0.0)
    unsigned chip_revision = efuse_hal_chip_revision();
    if (chip_revision == 300) {
        esp_psram_p4_rev3_workaround();
    }
#endif

    uint32_t psram_available_size = 0;
    ret = esp_psram_impl_get_available_size(&psram_available_size);
    assert(ret == ESP_OK);

    /**
     * `start_page` is the psram physical address in MMU page size.
     * MMU page size on ESP32S2 is 64KB
     * e.g.: psram physical address 16 is in page 0
     *
     * Here we plan to copy FLASH instructions to psram physical address 0, which is the No.0 page.
     */
    __attribute__((unused)) uint32_t start_page = 0;

#if CONFIG_SPIRAM_FETCH_INSTRUCTIONS || CONFIG_SPIRAM_RODATA
#if (CONFIG_IDF_TARGET_ESP32C5 && CONFIG_ESP32C5_REV_MIN_FULL <= 100) || (CONFIG_IDF_TARGET_ESP32C61 && CONFIG_ESP32C61_REV_MIN_FULL <= 100)
