/****************************************************************************
 * Name: __esp_start
 ****************************************************************************/

void __esp_start(void)
{
  esp_err_t ret;
  uint32_t psram_diag_stage = 0;

  ets_printf("P4BOOT:01 enter\n");

  esp_cpu_intr_set_ivt_addr(&_vector_table);

#if SOC_INT_CLIC_SUPPORTED
  /* When hardware vectored interrupts are enabled in CLIC,
   * the CPU jumps to this base address + 4 * interrupt_id.
   */

  esp_cpu_intr_set_mtvt_addr(&_mtvt_table);
#endif

#ifdef CONFIG_ESP_ROM_NEEDS_SET_CACHE_MMU_SIZE
  uint32_t _instruction_size;
  uint32_t cache_mmu_irom_size;
#endif

  bootloader_clear_bss_section();

#ifdef CONFIG_ESPRESSIF_SIMPLE_BOOT
  ets_printf("P4BOOT:02 bootloader_init\n");
  if (bootloader_init() != 0)
    {
      ets_printf("Hardware init failed, aborting\n");
      while (true);
    }

  ets_printf("P4BOOT:03 bootloader_ready\n");

  psram_diag_stage = REG_READ(LP_SYSTEM_REG_LP_STORE0_REG);
  REG_WRITE(LP_SYSTEM_REG_LP_STORE0_REG, 0);
  if (psram_diag_stage == 0x4e585354)
    {
      ets_printf("P4DIAG: reached_nx_start\n");
    }

#endif

  /* Initialize the per CPU areas */

#ifdef CONFIG_RISCV_PERCPU_SCRATCH
  riscv_percpu_add_hart(0);
#endif

#if defined(CONFIG_ESPRESSIF_BOOTLOADER_MCUBOOT) || \
    defined(CONFIG_ESPRESSIF_SIMPLE_BOOT)
  size_t partition_offset = PRIMARY_SLOT_OFFSET;
  uint32_t app_irom_start = partition_offset + (uint32_t)_image_irom_lma;
  uint32_t app_irom_size  = (uint32_t)_image_irom_size;
  uint32_t app_irom_vaddr = (uint32_t)_image_irom_vma;
  uint32_t app_drom_start = partition_offset + (uint32_t)_image_drom_lma;
  uint32_t app_drom_size  = (uint32_t)_image_drom_size;
  uint32_t app_drom_vaddr = (uint32_t)_image_drom_vma;

  if (map_rom_segments(app_drom_start, app_drom_vaddr, app_drom_size,
                       app_irom_start, app_irom_vaddr, app_irom_size) != 0)
    {
      ets_printf("Failed to setup XIP, aborting\n");
      while (true);
    }
#endif

#if CONFIG_ESP_ROM_NEEDS_SET_CACHE_MMU_SIZE
  _instruction_size = (uint32_t)&_instruction_reserved_end - \
                      (uint32_t)&_instruction_reserved_start;
  cache_mmu_irom_size =
      ((_instruction_size + SPI_FLASH_MMU_PAGE_SIZE - 1) / \
      SPI_FLASH_MMU_PAGE_SIZE) * sizeof(uint32_t);

  /* Configure the Cache MMU size for instruction and rodata in flash. */

  cache_set_idrom_mmu_size(cache_mmu_irom_size,
                           CACHE_DROM_MMU_MAX_END - cache_mmu_irom_size);
#endif /* CONFIG_ESP_ROM_NEEDS_SET_CACHE_MMU_SIZE */

#if CONFIG_ESP_SYSTEM_BBPLL_RECALIB
  recalib_bbpll();
#endif

#ifdef CONFIG_ESPRESSIF_REGION_PROTECTION
  /* Configure region protection */

  esp_cpu_configure_region_protection();
#endif

  /* Configure the power related stuff. */

  esp_rtc_init();

  ets_printf("P4BOOT:04 rtc_ready\n");

  esp_mspi_pin_init();

  ets_printf("P4BOOT:05 mspi_pins_ready\n");

  /* Configure SPI Flash chip state */

  bootloader_flash_update_id();
  spi_flash_init_chip_state();
  mspi_timing_flash_tuning();

  esp_mmu_map_init();

  ets_printf("P4BOOT:06 flash_mmu_ready\n");

  /* bootloader_init() has already brought up the MSPI and CPLL.  Complete
   * the application clock setup before enabling external RAM: changing the
   * RTC/CPU clock tree after PSRAM has been mapped destabilizes the shared
   * MSPI clock domain on this board.
   */

  esp_clk_init();

  ets_printf("P4BOOT:07 clocks_ready\n");

  /* The second-stage bootloader leaves the RTC watchdog enabled to guard
   * application startup.  PSRAM training and mapping can exceed that early
   * boot window, so hand the watchdog off before starting external RAM.
   */

  wdt_hal_context_t rwdt_ctx = RWDT_HAL_CONTEXT_DEFAULT();
  wdt_hal_write_protect_disable(&rwdt_ctx);
  wdt_hal_set_flashboot_en(&rwdt_ctx, false);
  wdt_hal_disable(&rwdt_ctx);
  wdt_hal_write_protect_enable(&rwdt_ctx);

  /* The ROM/second-stage path also enables the LP analog Super WDT.  Its
   * reset is reported as a full-chip/power-on reset rather than RWDT, so it
   * must be handed off separately before the relatively long PSRAM setup.
   */

  REG_WRITE(LP_WDT_SWD_WPROTECT_REG, LP_WDT_SWD_WKEY_VALUE);
  REG_SET_BIT(LP_WDT_SWD_CONFIG_REG, LP_WDT_SWD_DISABLE);
  REG_WRITE(LP_WDT_SWD_WPROTECT_REG, 0);

  ets_printf("P4BOOT:08 wdts_disabled\n");

#ifdef CONFIG_ESPRESSIF_SPIRAM
  ets_printf("P4BOOT:09 psram_chip_init\n");
  ret = esp_psram_chip_init();
  if (ret != ESP_OK)
    {
#  ifndef CONFIG_ESPRESSIF_SPIRAM_IGNORE_NOTFOUND
      PANIC();
#  endif
    }

#  ifdef CONFIG_ESPRESSIF_SPIRAM_BOOT_INIT
  if (ret == ESP_OK)
    {
      ret = esp_psram_init();
      if (ret != ESP_OK)
        {
#    ifndef CONFIG_ESPRESSIF_SPIRAM_IGNORE_NOTFOUND
          PANIC();
#    endif
        }

    }
#  endif
#endif

  esp_mspi_pin_reserve();

  bootloader_init_mem();

#ifdef CONFIG_ESPRESSIF_SPIRAM_MEMTEST
  if (esp_psram_is_initialized() && !esp_psram_extram_test())
    {
      PANIC();
    }
#endif

#ifdef CONFIG_ESPRESSIF_SPIRAM_ALLOW_BSS_SEG_EXTERNAL_MEMORY
  esp_psram_bss_init();
#endif

  /* Disable clock of unused peripherals */

  esp_perip_clk_init();

#ifdef CONFIG_ESPRESSIF_BROWNOUT_DET
  /* Initialize hardware brownout check and reset */

  esp_brownout_init();
#endif

  /* Configure the UART so we can get debug output */

  esp_lowsetup();

#ifdef USE_EARLYSERIALINIT
  /* Perform early serial initialization */

  riscv_earlyserialinit();
#endif

  esp_chip_revision_check();

  showprogress("A");

  /* Setup the syscall table needed by the ROM code */

  esp_setup_syscall_table();

  showprogress("B");

  showprogress("C");

  /* Initialize onboard resources */

  esp_board_initialize();

  showprogress("D");

  if (psram_diag_stage != 0x4e585354)
    {
      REG_WRITE(LP_SYSTEM_REG_LP_STORE0_REG, 0x4e585354);
      esp_rom_software_reset_system();
    }

  nx_start();

  UNUSED(ret);

  for (; ; );
}
